function BOX(frame, S):
    result = empty set
    for each world w in frame.worlds:
        succ = { v : (w, v) in frame.R }
        if succ is a subset of S:
            add w to result        # vacuously true when succ is empty
    return result

function DIAMOND(frame, S):
    result = empty set
    for each world w in frame.worlds:
        succ = { v : (w, v) in frame.R }
        if succ intersect S is nonempty:
            add w to result
    return result

