function SYNC_PRODUCT(F, G):
    worlds = { (a, b) : a in F.worlds, b in G.worlds }
    R = { ((a,b),(c,d)) : (a,c) in F.R and (b,d) in G.R }
    return (worlds, R)

function DIAMOND_FACTORS(F, G, A, B):
    P   = SYNC_PRODUCT(F, G)
    lhs = DIAMOND(P, { (a,b) : a in A, b in B })
    rhs = { (a,b) : a in DIAMOND(F, A), b in DIAMOND(G, B) }
    return lhs == rhs            # always True for GL frames

